import { describe, expect, it } from "vitest";
import { computeAll, enrichWithRefs, measure, projectCephStampedValues, type LandmarkMap } from "../lib/ceph";

// Owner/dot independent fixture, 2026-10-11. Isotropic image coordinates;
// expected angles supplied independently, not generated by the engine.
const points: LandmarkMap = { S: { x: 0, y: 0 }, N: { x: 10, y: 0 },
  Po: { x: 0, y: -20 }, Or: { x: 10 * Math.sqrt(3), y: -10 },
  Go: { x: 0, y: 10 }, Gn: { x: 10, y: 20 }, Me: { x: 10 * Math.sqrt(3), y: 0 } };
const steiner = "STEINER_SN_GOGN_V1", downs = "DOWNS_FH_GOME_V1";
describe("versioned mandibular-plane definitions", () => {
  it("distinguishes Steiner SN-GoGn=45 from Downs FH(Po-Or)-GoMe=60", () => {
    expect(measure(steiner, points, NaN)).toBeCloseTo(45, 10);
    expect(measure(downs, points, NaN)).toBeCloseTo(60, 10);
    // The historic mislabeled code keeps its old SN-GoMe geometry (30°).
    expect(measure("SNGOGN", points, NaN)).toBeCloseTo(30, 10);
    const swapped: LandmarkMap = { ...points, Me: points.Gn };
    expect(measure(downs, swapped, NaN)).toBeCloseTo(15, 10);
  });
  it("requires Gn only for Steiner and Me only for Downs", () => {
    const withoutGn = { ...points }; delete withoutGn.Gn;
    expect(measure(steiner, withoutGn, NaN)).toBeNaN();
    expect(measure(downs, withoutGn, NaN)).toBeCloseTo(60, 10);
    const withoutMe = { ...points }; delete withoutMe.Me;
    expect(measure(steiner, withoutMe, NaN)).toBeCloseTo(45, 10);
    expect(measure(downs, withoutMe, NaN)).toBeNaN();
  });
  it("does not manufacture a reference interval, classification or old-code identity for a new calculation", () => {
    const results = computeAll(points, NaN);
    expect(results.some(result => result.code === "SNGOGN")).toBe(false);
    for (const code of [steiner, downs]) {
      expect(results.find(result => result.code === code)).toMatchObject({ mean: null, tol: null, status: null,
        severityStars: "", interpretationAr: "", interpretationEn: "" });
    }
    const enriched = enrichWithRefs(results, { [steiner]: { mean: 32, sd: 5 }, [downs]: { mean: 25, sd: 3 } });
    for (const code of [steiner, downs]) expect(enriched.find(row => row.code === code)).toMatchObject({ refMean: null, refSd: null, z: null, refSeverity: null });
  });
  it("keeps old sealed codes and exact values without inventing successor values or cross-method deltas", () => {
    const sealed = [{ code: "SNGOGN", value: 31.678901234 }];
    const projected = projectCephStampedValues(sealed);
    expect(projected).toHaveLength(1);
    expect(projected[0]).toMatchObject({ code: "SNGOGN", value: 31.678901234, display: "31.7", mean: null, status: null });
    expect(projected[0].en).toContain("Historical SN–GoMe");
    expect(projectCephStampedValues([])).toEqual([]);
    expect(sealed).toEqual([{ code: "SNGOGN", value: 31.678901234 }]);
  });
  it("stores unrounded new geometry and rounds only its display; degenerate planes remain unavailable", () => {
    const revised = { ...points, Gn: { x: 1, y: 10 + Math.SQRT2 } };
    const result = computeAll(revised, NaN).find(row => row.code === steiner)!;
    expect(result.value).toBeCloseTo(54.735610317245346, 10);
    expect(result.display).toBe("54.7"); expect(result.value).not.toBe(Number(result.display));
    expect(measure(steiner, { ...points, Gn: points.Go }, NaN)).toBeNaN();
    expect(measure(downs, { ...points, Or: points.Po }, NaN)).toBeNaN();
  });
});
